select , u.location, u.tenant_id, u.client_id
from user_info u left join user_role_rel r on u.id = r.user_id
where r.role_id = #{roleId,jdbcType=BIGINT}

select , u.location, u.tenant_id, u.client_id
from user_info u left join user_group_rel r on u.id = r.user_id
where r.group_id = #{groupId,jdbcType=BIGINT}

select , u.location, u.tenant_id, u.client_id
from user_info u left join user_org_rel r on u.id = r.user_id
where r.org_id = #{orgId,jdbcType=BIGINT}

select

,  AS point
from user_info u
where 1 = 2

    or openid = #{user.openid,jdbcType=VARCHAR}


    or weixinid = #{user.weixinid,jdbcType=VARCHAR}


    or weiboid = #{user.weiboid,jdbcType=VARCHAR}


    or githubid = #{user.githubid,jdbcType=VARCHAR}


    or jiacn = #{user.jiacn,jdbcType=VARCHAR}


    or phone LIKE CONCAT('%',#{user.phone,jdbcType=VARCHAR},'%')


    or email LIKE CONCAT('%',#{user.email,jdbcType=VARCHAR},'%')


    or sex = #{user.sex,jdbcType=INTEGER}


    or nickname LIKE CONCAT('%',#{user.nickname,jdbcType=VARCHAR},'%')


    or city LIKE CONCAT('%',#{user.city,jdbcType=VARCHAR},'%')


    or country LIKE CONCAT('%',#{user.country,jdbcType=VARCHAR},'%')


    or province LIKE CONCAT('%',#{user.province,jdbcType=VARCHAR},'%')


    or latitude = #{user.latitude,jdbcType=VARCHAR}


    or longitude = #{user.longitude,jdbcType=VARCHAR}


    or COALESCE((SELECT pa.balance FROM point_account pa
        WHERE pa.tenant_id = #{pointTenantId,jdbcType=VARCHAR}
          AND OCTET_LENGTH(pa.tenant_id) = OCTET_LENGTH(#{pointTenantId,jdbcType=VARCHAR})
          AND pa.jiacn = u.jiacn
          AND CAST(pa.jiacn AS BINARY) = CAST(u.jiacn AS BINARY)), 0) = #{user.point,jdbcType=INTEGER}


    or referrer LIKE CONCAT('%',#{user.referrer,jdbcType=VARCHAR},'%')


    or birthday = #{user.birthday,jdbcType=DATE}


    or create_time = #{user.createTime,jdbcType=BIGINT}


    or update_time = #{user.updateTime,jdbcType=BIGINT}

SELECT relation_user_id AS userId, relation_type AS relationType, relation_id AS relationId FROM ( SELECT user_id AS relation_user_id, 'ROLE' AS relation_type, role_id AS relation_id, id AS relation_row_id FROM user_role_rel WHERE user_id IN
#{userId,jdbcType=BIGINT}
UNION ALL SELECT user_id AS relation_user_id, 'ORG' AS relation_type, org_id AS relation_id, id AS relation_row_id FROM user_org_rel WHERE user_id IN
#{userId,jdbcType=BIGINT}
UNION ALL SELECT user_id AS relation_user_id, 'GROUP' AS relation_type, group_id AS relation_id, id AS relation_row_id FROM user_group_rel WHERE user_id IN
#{userId,jdbcType=BIGINT}
) relation_rows ORDER BY relation_user_id, relation_type, relation_row_id

SELECT id, jiacn, account_state, auth_epoch
FROM user_info
WHERE id = #{userId,jdbcType=BIGINT}

mapper.update:
UPDATE user_info
SET auth_epoch = auth_epoch + 1
WHERE id = #{userId,jdbcType=BIGINT}
  AND auth_epoch = #{expectedEpoch,jdbcType=BIGINT}
  AND account_state = _ascii'ACTIVE' COLLATE ascii_bin
  AND auth_epoch < 9223372036854775807
